contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint voteID, uint oldID, uint newID, string memory typeStr)
        public
    {
        require(oldID != newID, "IDs must differ");

        // Create two proposals of the same type so the cancel precondition can hold.
        c.newAddressProposal(address(uint160(oldID + 1)), typeStr);
        c.newAddressProposal(address(uint160(newID + 1)), typeStr);

        // Ensure the old proposal is finalising by making it reach quorum if possible.
        try c.voteProposal(oldID) {} catch {}
        try c.voteProposal(newID) {} catch {}

        // Drive cancelProposal(proposalID) via the only available public entry that
        // can accept arbitrary proposal IDs.
        (bool ok, ) = address(c).call(abi.encodeWithSignature("cancelProposal(uint256,uint256)", oldID, newID));
        require(ok, "cancelProposal must succeed");

        assert(c.mapPID_votes(oldID) == 0);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint oldID, uint newID, string memory typeStr) public {
        require(oldID != newID, "IDs must differ");

        c.newAddressProposal(address(uint160(oldID + 1)), typeStr);
        c.newAddressProposal(address(uint160(newID + 1)), typeStr);

        try c.voteProposal(oldID) { } catch { }
        try c.voteProposal(newID) { } catch { }

        bool reverted;
        try c.cancelProposal(oldID, newID) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted || c.mapPID_votes(oldID) == 0);
    }

    receive() external payable {}
}

